{"command":"cat <<'EOF' > oviewer/config.go
package oviewer

import (
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

type Config struct {
	QuitSmall           *bool                    `yaml:"QuitSmall,omitempty"`
	IsWriteOriginal     *bool                    `yaml:"IsWriteOriginal,omitempty"`
	BeforeWriteOriginal int                      `yaml:"BeforeWriteOriginal,omitempty"`
	AfterWriteOriginal  int                      `yaml:"AfterWriteOriginal,omitempty"`
	CaseSensitive       *bool                    `yaml:"CaseSensitive,omitempty"`
	SmartCaseSensitive  *bool                    `yaml:"SmartCaseSensitive,omitempty"`
	RegexpSearch        *bool                    `yaml:"RegexpSearch,omitempty"`
	Incsearch           *bool                    `yaml:"Incsearch,omitempty"`
	MemoryLimit         int                      `yaml:"MemoryLimit,omitempty"`
	MemoryLimitFile     int                      `yaml:"MemoryLimitFile,omitempty"`
	DisableMouse        *bool                    `yaml:"DisableMouse,omitempty"`
	DisableColumnCycle  *bool                    `yaml:"DisableColumnCycle,omitempty"`
	DisableStickyFollow *bool                    `yaml:"DisableStickyFollow,omitempty"`
	ViewMode            string                   `yaml:"ViewMode,omitempty"`
	ClipboardMethod     string                   `yaml:"ClipboardMethod,omitempty"`
	SetTerminalTitle    *bool                    `yaml:"SetTerminalTitle,omitempty"`
	Debug               *bool                    `yaml:"Debug,omitempty"`
	ShrinkChar          string                   `yaml:"ShrinkChar,omitempty"`
	ReadWaitTime        string                   `yaml:"ReadWaitTime,omitempty"`
	General             GeneralConfig            `yaml:"General,omitempty"`
	StyleOverStrike     StyleConfig              `yaml:"StyleOverStrike,omitempty"`
	StyleOverLine       StyleConfig              `yaml:"StyleOverLine,omitempty"`
	DefaultKeyBind      string                   `yaml:"DefaultKeyBind,omitempty"`
	KeyBind             map[string][]string      `yaml:"KeyBind,omitempty"`
	Mode                map[string]GeneralConfig `yaml:"Mode,omitempty"`
}

type GeneralConfig struct {
	TabWidth         int                    `yaml:"TabWidth,omitempty"`
	Header           int                    `yaml:"Header,omitempty"`
	AlternateRows    *bool                  `yaml:"AlternateRows,omitempty"`
	ColumnMode       *bool                  `yaml:"ColumnMode,omitempty"`
	LineNumMode      *bool                  `yaml:"LineNumMode,omitempty"`
	WrapMode         *bool                  `yaml:"WrapMode,omitempty"`
	ColumnDelimiter  string                 `yaml:"ColumnDelimiter,omitempty"`
	MarkStyleWidth   int                    `yaml:"MarkStyleWidth,omitempty"`
	HScrollWidth     string                 `yaml:"HScrollWidth,omitempty"`
	VScrollLines     int                    `yaml:"VScrollLines,omitempty"`
	SectionDelimiter string                 `yaml:"SectionDelimiter,omitempty"`
	SectionHeader    *bool                  `yaml:"SectionHeader,omitempty"`
	SectionHeaderNum int                    `yaml:"SectionHeaderNum,omitempty"`
	SectionStart     int                    `yaml:"SectionStart,omitempty"`
	HideOtherSection *bool                  `yaml:"HideOtherSection,omitempty"`
	Prompt           PromptConfig           `yaml:"Prompt,omitempty"`
	Style            map[string]interface{} `yaml:"Style,omitempty"`
}

type PromptConfig struct {
	Normal NormalPrompt `yaml:"Normal,omitempty"`
	Input  InputPrompt  `yaml:"Input,omitempty"`
}

type NormalPrompt struct {
	ShowFilename   *bool `yaml:"ShowFilename,omitempty"`
	InvertColor    *bool `yaml:"InvertColor,omitempty"`
	ProcessOfCount *bool `yaml:"ProcessOfCount,omitempty"`
	CursorType     int   `yaml:"CursorType,omitempty"`
}

type InputPrompt struct {
	CursorType int `yaml:"CursorType,omitempty"`
}

type StyleConfig struct {
	Foreground     string `yaml:"Foreground,omitempty"`
	Background     string `yaml:"Background,omitempty"`
	UnderlineColor string `yaml:"UnderlineColor,omitempty"`
	Bold           *bool  `yaml:"Bold,omitempty"`
	Blink          *bool  `yaml:"Blink,omitempty"`
	Dim            *bool  `yaml:"Dim,omitempty"`
	Italic         *bool  `yaml:"Italic,omitempty"`
	Underline      *bool  `yaml:"Underline,omitempty"`
	Reverse        *bool  `yaml:"Reverse,omitempty"`
	UnderlineStyle int    `yaml:"UnderlineStyle,omitempty"`
}

func DefaultConfig() Config {
	tr := true
	return Config{
		MemoryLimit:     -1,
		MemoryLimitFile: 100,
		General: GeneralConfig{
			TabWidth:        8,
			WrapMode:        &tr,
			ColumnDelimiter: ",",
		},
	}
}

func FindConfigFile(configPath string) (string, bool) {
	if configPath != "" {
		if _, err := os.Stat(configPath); err == nil {
			return configPath, true
		}
		return configPath, false
	}
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		p := filepath.Join(xdg, "ov", "config.yaml")
		if _, err := os.Stat(p); err == nil {
			return p, true
		}
	}
	if home, err := os.UserHomeDir(); err == nil {
		p := filepath.Join(home, ".config", "ov", "config.yaml")
		if _, err := os.Stat(p); err == nil {
			return p, true
		}
	}
	return "", false
}

func LoadConfig(configPath string) (Config, error) {
	cfg := DefaultConfig()
	if configPath == "" {
		path, ok := FindConfigFile("")
		if !ok {
			return cfg, nil
		}
		configPath = path
	}
	data, err := os.ReadFile(configPath)
	if err != nil {
		return cfg, err
	}
	err = yaml.Unmarshal(data, &cfg)
	return cfg, err
}
EOF"}

