package oviewer

import (
	"bufio"
	"compress/bzip2"
	"compress/gzip"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
)

type Document struct {
	FileName string
	Caption  string
	lines    []string
	mu       sync.RWMutex
	eof      bool
	reader   io.ReadCloser
	cmd      *exec.Cmd
}

func NewDocument(filename string, skipExtract bool) (*Document, error) {
	doc := &Document{
		FileName: filename,
		lines:    make([]string, 0, 100),
	}

	var r io.ReadCloser
	var err error

	if filename == "" || filename == "-" {
		doc.FileName = "STDIN"
		r = io.NopCloser(os.Stdin)
	} else {
		file, err := os.Open(filename)
		if err != nil {
			return nil, err
		}
		r = file

		if !skipExtract {
			ext := strings.ToLower(filepath.Ext(filename))
			switch ext {
			case ".gz":
				gzr, err := gzip.NewReader(file)
				if err == nil {
					r = gzr
				}
			case ".bz2":
				r = io.NopCloser(bzip2.NewReader(file))
			case ".xz":
				file.Close()
				cmd := exec.Command("xzcat", filename)
				out, err := cmd.StdoutPipe()
				if err == nil && cmd.Start() == nil {
					r = out
					doc.cmd = cmd
				} else {
					file, _ = os.Open(filename)
					r = file
				}
			case ".zst":
				file.Close()
				cmd := exec.Command("zstdcat", filename)
				out, err := cmd.StdoutPipe()
				if err == nil && cmd.Start() == nil {
					r = out
					doc.cmd = cmd
				} else {
					file, _ = os.Open(filename)
					r = file
				}
			case ".lz4":
				file.Close()
				cmd := exec.Command("lz4cat", filename)
				out, err := cmd.StdoutPipe()
				if err == nil && cmd.Start() == nil {
					r = out
					doc.cmd = cmd
				} else {
					file, _ = os.Open(filename)
					r = file
				}
			}
		}
	}

	doc.reader = r
	go doc.readLoop()

	return doc, nil
}

func NewDocumentExec(args []string) (*Document, error) {
	if len(args) == 0 {
		return nil, os.ErrNotExist
	}
	cmd := exec.Command(args[0], args[1:]...)
	out, err := cmd.StdoutPipe()
	if err != nil {
		return nil, err
	}
	if err := cmd.Start(); err != nil {
		return nil, err
	}
	doc := &Document{
		FileName: strings.Join(args, " "),
		lines:    make([]string, 0, 100),
		reader:   out,
		cmd:      cmd,
	}
	go doc.readLoop()
	return doc, nil
}

func (d *Document) readLoop() {
	if d.reader == nil {
		d.mu.Lock()
		d.eof = true
		d.mu.Unlock()
		return
	}
	defer d.reader.Close()

	scanner := bufio.NewScanner(d.reader)
	// Handle long lines
	buf := make([]byte, 64*1024)
	scanner.Buffer(buf, 1024*1024)

	for scanner.Scan() {
		line := scanner.Text()
		d.mu.Lock()
		d.lines = append(d.lines, line)
		d.mu.Unlock()
	}

	d.mu.Lock()
	d.eof = true
	d.mu.Unlock()

	if d.cmd != nil {
		d.cmd.Wait()
	}
}

func (d *Document) NumLines() int {
	d.mu.RLock()
	defer d.mu.RUnlock()
	return len(d.lines)
}

func (d *Document) GetLine(n int) string {
	d.mu.RLock()
	defer d.mu.RUnlock()
	if n < 0 || n >= len(d.lines) {
		return ""
	}
	return d.lines[n]
}

func (d *Document) AllLines() []string {
	d.mu.RLock()
	defer d.mu.RUnlock()
	cp := make([]string, len(d.lines))
	copy(cp, d.lines)
	return cp
}
EOF"}

