			}
			if modeCfg.ColumnMode != nil {
				r.ColumnMode = *modeCfg.ColumnMode
			}
			if modeCfg.AlternateRows != nil {
				r.AlternateRows = *modeCfg.AlternateRows
			}
			if modeCfg.ColumnDelimiter != "" {
				r.ColumnDelim = modeCfg.ColumnDelimiter
			}
		}
	}

	s, err := tcell.NewScreen()
	if err != nil {
		return err
	}
	if err := s.Init(); err != nil {
		return err
	}
	defer s.Fini()

	s.EnableMouse()
	r.Screen = s

	r.RunLoop()

	if r.ExitWrite {
		s.Fini()
		r.PrintCurrentScreen(termWidth, termHeight)
	}

	return nil
}

func (r *Root) RunLoop() {
	s := r.Screen

	for {
		s.Clear()
		w, h := s.Size()

		doc := r.Docs[r.DocNum]
		totalLines := doc.NumLines()

		bodyHeight := h - 1 - r.Header
		if bodyHeight < 1 {
			bodyHeight = 1
		}

		// Draw Header
		for i := 0; i < r.Header && i < totalLines; i++ {
			line := doc.GetLine(i)
			r.DrawLine(i, i, line, w, true)
		}

		// Draw Body
		for y := 0; y < bodyHeight; y++ {
			lineIdx := r.Header + r.TopLN + y
			if lineIdx >= totalLines {
				// Fill empty lines with ~
				r.DrawString(0, r.Header+y, tcell.StyleDefault.Foreground(tcell.ColorColor8), "~")
			} else {
				line := doc.GetLine(lineIdx)
				r.DrawLine(r.Header+y, lineIdx, line, w, false)
			}
		}

		// Draw Status Line
		r.DrawStatusLine(w, h-1, doc, totalLines)

		s.Show()

		ev := s.PollEvent()
		switch ev := ev.(type) {
		case *tcell.EventKey:
			switch ev.Key() {
			case tcell.KeyEscape, tcell.KeyRune:
				if ev.Key() == tcell.KeyEscape || ev.Rune() == 'q' {
					return
				}
				if ev.Rune() == 'Q' {
					r.ExitWrite = true
					return
				}
				if ev.Rune() == 'w' || ev.Rune() == 'W' {
					r.WrapMode = !r.WrapMode
				}
				if ev.Rune() == 'c' {
					r.ColumnMode = !r.ColumnMode
				}
				if ev.Rune() == 'C' {
					r.AlternateRows = !r.AlternateRows
				}
				if ev.Rune() == 'G' {
					r.LineNumMode = !r.LineNumMode
				}
				if ev.Rune() == ']' {
					if r.DocNum+1 < len(r.Docs) {
						r.DocNum++
						r.TopLN = 0
					}
				}
				if ev.Rune() == '[' {
					if r.DocNum > 0 {
						r.DocNum--
						r.TopLN = 0
					}
				}
			case tcell.KeyDown, tcell.KeyEnter:
				if r.Header+r.TopLN+1 < totalLines {
					r.TopLN++
				}
			case tcell.KeyUp:
				if r.TopLN > 0 {
					r.TopLN--
				}
			case tcell.KeyPgDn:
				if r.TopLN+bodyHeight < totalLines {
					r.TopLN += bodyHeight
				} else {
					r.TopLN = totalLines - bodyHeight
					if r.TopLN < 0 {
						r.TopLN = 0
					}
				}
			case tcell.KeyPgUp:
				r.TopLN -= bodyHeight
				if r.TopLN < 0 {
					r.TopLN = 0
				}
			case tcell.KeyHome:
				r.TopLN = 0
			case tcell.KeyEnd:
				r.TopLN = totalLines - bodyHeight
				if r.TopLN < 0 {
					r.TopLN = 0
				}
			}
		case *tcell.EventResize:
			s.Sync()
		}
	}
}

func (r *Root) DrawLine(screenY, lineIdx int, line string, width int, isHeader bool) {
	style := tcell.StyleDefault
	if isHeader {
		style = style.Bold(true)
	} else if r.AlternateRows && lineIdx%2 == 1 {
		style = style.Background(tcell.ColorColor8)
	}

	x := 0
	if r.LineNumMode {
		numStr := fmt.Sprintf("%2d ", lineIdx+1)
		r.DrawString(0, screenY, style.Foreground(tcell.ColorYellow), numStr)
		x += len(numStr)
	}

	// Expand tabs
	tabExpanded := strings.ReplaceAll(line, "\t", strings.Repeat(" ", r.TabWidth))
	if !r.WrapMode && len(tabExpanded) > width-x {
		tabExpanded = tabExpanded[:width-x]
	}

	r.DrawString(x, screenY, style, tabExpanded)
}

func (r *Root) DrawString(x, y int, style tcell.Style, str string) {
	for i, ch := range str {
		r.Screen.SetContent(x+i, y, ch, nil, style)
	}
}

func (r *Root) DrawStatusLine(width, screenY int, doc *Document, totalLines int) {
	prefix := ""
	if len(r.Docs) > 1 {
		prefix = fmt.Sprintf("[%d]", r.DocNum)
	}
	fname := doc.FileName + ":"

	curLine := r.Header + r.TopLN + 1
	if curLine > totalLines {
		curLine = totalLines
	}
	if totalLines == 0 {
		curLine = 0
	}
	posStr := fmt.Sprintf("(%d/%d)", curLine, totalLines)

	// Filename in reverse style
	promptStyle := tcell.StyleDefault.Reverse(true)
	statusStr := prefix + fname

	r.DrawString(0, screenY, promptStyle, statusStr)

	// Right aligned position
	posX := width - len(posStr)
	if posX > len(statusStr) {
		r.DrawString(posX, screenY, tcell.StyleDefault, posStr)
	}
}

func (r *Root) PrintCurrentScreen(width, height int) {
	doc := r.Docs[r.DocNum]
	lines := doc.AllLines()
	for i := 0; i < len(lines); i++ {
		fmt.Println(lines[i])
	}
}
EOF"}

