{"command":"cat <<'EOF' > oviewer/oviewer.go
package oviewer

import (
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/gdamore/tcell/v2"
	"github.com/mattn/go-isatty"
	"golang.org/x/term"
)

type Root struct {
	Screen        tcell.Screen
	Docs          []*Document
	DocNum        int
	Config        Config
	Flags         *Flags
	TopLN         int
	LeftLX        int
	WrapMode      bool
	ColumnMode    bool
	LineNumMode   bool
	AlternateRows bool
	Header        int
	TabWidth      int
	ColumnDelim   string
	ExitWrite     bool
}

func RunRoot(cfg Config, flags *Flags, args []string) error {
	stdinTTY := isatty.IsTerminal(os.Stdin.Fd()) || isatty.IsCygwinTerminal(os.Stdin.Fd())
	stdoutTTY := isatty.IsTerminal(os.Stdout.Fd()) || isatty.IsCygwinTerminal(os.Stdout.Fd())

	var docs []*Document

	if flags.Exec {
		if len(args) == 0 {
			return fmt.Errorf("Error: missing command")
		}
		doc, err := NewDocumentExec(args)
		if err != nil {
			return fmt.Errorf("Error: %w", err)
		}
		docs = append(docs, doc)
	} else if len(args) == 0 {
		if stdinTTY {
			fmt.Fprintln(os.Stderr, "Error: missing file")
			os.Exit(1)
		}
		doc, err := NewDocument("", flags.SkipExtract)
		if err != nil {
			return fmt.Errorf("Error: %w", err)
		}
		docs = append(docs, doc)
	} else {
		for _, arg := range args {
			doc, err := NewDocument(arg, flags.SkipExtract)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %s\n", err)
				os.Exit(1)
			}
			docs = append(docs, doc)
		}
	}

	time.Sleep(20 * time.Millisecond)

	if !stdoutTTY && !flags.ForceScreen {
		if len(docs) > 0 {
			doc := docs[0]
			for i := 0; i < 50 && doc.NumLines() == 0 && !doc.eof; i++ {
				time.Sleep(10 * time.Millisecond)
			}
			lines := doc.AllLines()
			for _, line := range lines {
				fmt.Println(line)
			}
		}
		return nil
	}

	termWidth, termHeight, err := term.GetSize(int(os.Stdout.Fd()))
	if err != nil || termHeight <= 0 {
		termWidth, termHeight = 80, 24
	}

	doc := docs[0]

	if flags.QuitIfOneScreen {
		for i := 0; i < 50 && doc.NumLines() < termHeight && !doc.eof; i++ {
			time.Sleep(10 * time.Millisecond)
		}
		if doc.NumLines() <= termHeight {
			lines := doc.AllLines()
			for _, line := range lines {
				fmt.Println(line)
			}
			return nil
		}
	}

	r := &Root{
		Docs:          docs,
		DocNum:        0,
		Config:        cfg,
		Flags:         flags,
		WrapMode:      flags.Wrap,
		ColumnMode:    flags.ColumnMode,
		LineNumMode:   flags.LineNumber,
		AlternateRows: flags.AlternateRows,
		Header:        flags.Header,
		TabWidth:      flags.TabWidth,
		ColumnDelim:   flags.ColumnDelimiter,
		ExitWrite:     flags.ExitWrite,
	}

	if flags.TabWidth == 0 {
		r.TabWidth = 8
	}

	if flags.ViewMode != "" {
		if modeCfg, ok := cfg.Mode[flags.ViewMode]; ok {
			if modeCfg.Header > 0 {
				r.Header = modeCfg.Header
			}
			if modeCfg.WrapMode != nil {
				r.WrapMode = *modeCfg.WrapMode
			}
			if modeCfg.ColumnMode != nil {
				r.ColumnMode = *modeCfg.ColumnMode
			}
			if modeCfg.AlternateRows != nil {
				r.AlternateRows = *modeCfg.AlternateRows
			}
			if modeCfg.ColumnDelimiter != "" {
				r.ColumnDelim = modeCfg.ColumnDelimiter
			}
		}
	}

	s, err := tcell.NewScreen()
	if err != nil {
		return err
	}
	if err := s.Init(); err != nil {
		return err
	}
	defer s.Fini()

	s.EnableMouse()
	r.Screen = s

	r.RunLoop()

	if r.ExitWrite {
		s.Fini()
		r.PrintCurrentScreen(termWidth, termHeight)
	}

	return nil
}

func (r *Root) RunLoop() {
	s := r.Screen

	for {
		s.Clear()
		w, h := s.Size()

		doc := r.Docs[r.DocNum]
		totalLines := doc.NumLines()

		bodyHeight := h - 1 - r.Header
		if bodyHeight < 1 {
			bodyHeight = 1
		}

		for i := 0; i < r.Header && i < totalLines; i++ {
			line := doc.GetLine(i)
			r.DrawLine(i, i, line, w, true)
		}

		for y := 0; y < bodyHeight; y++ {
			lineIdx := r.Header + r.TopLN + y
			if lineIdx >= totalLines {
