	ColumnWidth        bool
	Completion         string
	Config             string
	Converter          string
	Debug              bool
	DisableColumnCycle bool
	DisableMouse       bool
	Exec               bool
	ExitWrite          bool
	ExitWriteAfter     int
	ExitWriteBefore    int
	Filter             string
	FollowAll          bool
	FollowMode         bool
	FollowName         bool
	FollowSection      bool
	ForceScreen        bool
	Header             int
	HeaderColumn       int
	HelpKey            bool
	HideOtherSection   bool
	HscrollWidth       string
	Incsearch          bool
	JumpTarget         string
	LineNumber         bool
	ListViewModes      bool
	MemoryLimit        int
	MemoryLimitFile    int
	MultiColor         []string
	NonMatchFilter     string
