}

func Execute() {
	var flags Flags

	rootCmd := &cobra.Command{
		Use:   "ov [flags] [FILE]...",
		Short: "ov is a feature rich pager(such as more/less).\nIt supports various compressed files(gzip, bzip2, zstd, lz4, and xz).",
		RunE: func(cmd *cobra.Command, args []string) error {
			if flags.Version {
				fmt.Printf("ov version %s rev:%s\n", Version, Revision)
				return nil
			}
			if flags.HelpKey {
				fmt.Print(HelpKey())
				return nil
			}
			if flags.Completion != "" {
				switch flags.Completion {
				case "bash":
					return cmd.GenBashCompletion(os.Stdout)
				case "zsh":
					return cmd.GenZshCompletion(os.Stdout)
				case "fish":
					return cmd.GenFishCompletion(os.Stdout, true)
				case "powershell":
					return cmd.GenPowerShellCompletion(os.Stdout)
				default:
					return fmt.Errorf("requires one of the arguments bash/zsh/fish/powershell")
				}
			}

			cfgPath := flags.Config
			cfg, err := LoadConfig(cfgPath)
			if err != nil && flags.Config != "" {
				fmt.Printf("failed to read config file: %s\n", err)
				return nil
			}

			if flags.ListViewModes {
				modes := []string{"general"}
				for m := range cfg.Mode {
					if m != "general" {
						modes = append(modes, m)
					}
				}
				sort.Strings(modes)
				for _, m := range modes {
					fmt.Println(m)
				}
				return nil
			}

			return RunRoot(cfg, &flags, args)
		},
	}

	rootCmd.SetHelpTemplate(`{{.Short}}

Usage:
  {{.UseLine}}

Flags:
Short   Long                                    Purpose
{{.Flags.FlagUsages}}`)

	f := rootCmd.Flags()

	f.BoolVarP(&flags.Align, "align", "l", false, "align the output columns for better readability")
	f.BoolVarP(&flags.AlternateRows, "alternate-rows", "C", false, "alternately change the line color")
	f.StringVar(&flags.Caption, "caption", "", "custom caption")
	f.BoolVarP(&flags.CaseSensitive, "case-sensitive", "i", false, "case-sensitive in search")
	f.StringVarP(&flags.ColumnDelimiter, "column-delimiter", "d", ",", "column delimiter character")
	f.Lookup("column-delimiter").Value = &customTypeValue{val: &flags.ColumnDelimiter, typeName: "character"}

	f.BoolVarP(&flags.ColumnMode, "column-mode", "c", false, "column mode")
	f.BoolVar(&flags.ColumnRainbow, "column-rainbow", false, "column mode to rainbow")
	f.BoolVar(&flags.ColumnWidth, "column-width", false, "column mode for width")
	f.StringVar(&flags.Completion, "completion", "", "generate completion script [bash|zsh|fish|powershell]")

	f.StringVar(&flags.Config, "config", "", "config file (default is $XDG_CONFIG_HOME/ov/config.yaml)")
	f.Lookup("config").Value = &customTypeValue{val: &flags.Config, typeName: "file"}

	f.StringVar(&flags.Converter, "converter", "es", "converter [es|raw|align]")
	f.BoolVar(&flags.Debug, "debug", false, "debug mode")
	f.BoolVar(&flags.DisableColumnCycle, "disable-column-cycle", false, "disable column cycling")
	f.BoolVar(&flags.DisableMouse, "disable-mouse", false, "disable mouse support")
	f.BoolVarP(&flags.Exec, "exec", "e", false, "command execution result instead of file")
	f.BoolVarP(&flags.ExitWrite, "exit-write", "X", false, "output the current screen when exiting")
	f.IntVarP(&flags.ExitWriteAfter, "exit-write-after", "a", 0, "number after the current lines when exiting")
	f.IntVarP(&flags.ExitWriteBefore, "exit-write-before", "b", 0, "number before the current lines when exiting")
	f.StringVar(&flags.Filter, "filter", "", "filter search pattern")
	f.BoolVarP(&flags.FollowAll, "follow-all", "A", false, "follow multiple files and show the most recently updated one")
	f.BoolVarP(&flags.FollowMode, "follow-mode", "f", false, "monitor file and display new content as it is written")
	f.BoolVar(&flags.FollowName, "follow-name", false, "follow mode to monitor by file name")
	f.BoolVar(&flags.FollowSection, "follow-section", false, "section-by-section follow mode")
	f.BoolVar(&flags.ForceScreen, "force-screen", false, "display screen even when redirecting output")
	f.IntVarP(&flags.Header, "header", "H", 0, "number of header lines to be displayed constantly")
	f.IntVarP(&flags.HeaderColumn, "header-column", "Y", 0, "number of columns to display as a vertical header")
	f.BoolVarP(&flags.HelpKey, "help-key", "", false, "display key bind information")
	f.BoolVar(&flags.HideOtherSection, "hide-other-section", false, "hide other section")

	f.StringVar(&flags.HscrollWidth, "hscroll-width", "10%", "width to scroll horizontally [int|int%|.int]")
	f.Lookup("hscroll-width").Value = &customTypeValue{val: &flags.HscrollWidth, typeName: "[int|int%|.int]", defaultStr: "\"10%\""}

	f.BoolVar(&flags.Incsearch, "incsearch", true, "incremental search")
	f.Lookup("incsearch").Value = &customTypeValueBool{val: &flags.Incsearch, typeName: "[=true|false]", defaultStr: "true"}

	f.StringVarP(&flags.JumpTarget, "jump-target", "j", "", "jump target [int|int%|.int|'section']")
	f.Lookup("jump-target").Value = &customTypeValue{val: &flags.JumpTarget, typeName: "[int|int%|.int|'section']"}

	f.BoolVarP(&flags.LineNumber, "line-number", "n", false, "line number mode")
	f.BoolVar(&flags.ListViewModes, "list-view-modes", false, "list available view modes defined in the configuration file")
	f.IntVar(&flags.MemoryLimit, "memory-limit", -1, "number of chunks to limit in memory")
	f.IntVar(&flags.MemoryLimitFile, "memory-limit-file", 100, "number of chunks to limit in memory for the file")
	f.StringSliceVarP(&flags.MultiColor, "multi-color", "M", nil, "comma separated words(regexp) to color .e.g. \"ERROR,WARNING\"")
	f.StringVar(&flags.NonMatchFilter, "non-match-filter", "", "filter non match search pattern")
	f.IntVar(&flags.NotifyEOF, "notify-eof", 0, "notify at the end of the file")
	f.StringVar(&flags.Pattern, "pattern", "", "search pattern")
	f.BoolVarP(&flags.Plain, "plain", "p", false, "disable original decoration")
	f.BoolVarP(&flags.QuitIfOneScreen, "quit-if-one-screen", "F", false, "quit if the output fits on one screen")
	f.BoolVarP(&flags.Raw, "raw", "r", false, "raw escape sequences without processing")
	f.BoolVar(&flags.RegexpSearch, "regexp-search", false, "regular expression search")
	f.IntVar(&flags.Ruler, "ruler", 0, "display ruler (=0: none, =1: relative, =2: absolute)")
	f.StringVar(&flags.SectionDelimiter, "section-delimiter", "", "regexp for section delimiter .e.g. \"^#\"")
	f.Lookup("section-delimiter").Value = &customTypeValue{val: &flags.SectionDelimiter, typeName: "regexp"}

	f.BoolVar(&flags.SectionHeader, "section-header", false, "enable section-delimiter line as Header")
	f.IntVar(&flags.SectionHeaderNum, "section-header-num", 1, "number of section header lines")
	f.IntVar(&flags.SectionStart, "section-start", 0, "section start position")
	f.BoolVar(&flags.SetTerminalTitle, "set-terminal-title", false, "set terminal title")
	f.BoolVar(&flags.SkipExtract, "skip-extract", false, "skip extracting compressed files")
	f.IntVar(&flags.SkipLines, "skip-lines", 0, "skip the number of lines")
	f.BoolVar(&flags.SmartCaseSensitive, "smart-case-sensitive", false, "smart case-sensitive in search")

	f.BoolVar(&flags.StatusLine, "status-line", true, "status line")
	f.Lookup("status-line").Value = &customTypeValueBool{val: &flags.StatusLine, typeName: "[=true|false]", defaultStr: "true"}

	f.IntVarP(&flags.TabWidth, "tab-width", "x", 8, "tab stop width")
	f.BoolVarP(&flags.Version, "version", "v", false, "display version information")
	f.IntVarP(&flags.VerticalHeader, "vertical-header", "y", 0, "number of characters to display as a vertical header")
	f.StringVarP(&flags.ViewMode, "view-mode", "m", "", "apply predefined settings for a specific mode")
	f.IntVarP(&flags.Watch, "watch", "T", 0, "watch mode interval(seconds)")
	f.Lookup("watch").Value = &customTypeValueInt{val: &flags.Watch, typeName: "seconds"}

	f.BoolVar(&flags.Wrap, "wrap", true, "wrap mode")
	f.Lookup("wrap").Value = &customTypeValueBool{val: &flags.Wrap, typeName: "[=true|false]", defaultStr: "true"}

	if err := rootCmd.Execute(); err != nil {
		os.Exit(1)
	}
}

type customTypeValue struct {
	val        *string
	typeName   string
	defaultStr string
}

func (c *customTypeValue) String() string {
	if c.defaultStr != "" {
		return c.defaultStr
	}
	if c.val != nil && *c.val != "" {
		if c.typeName == "character" {
			return fmt.Sprintf("%q", *c.val)
		}
		return *c.val
	}
	if c.typeName == "character" {
		return `","`
	}
	return ""
}

func (c *customTypeValue) Set(s string) error {
	*c.val = s
	return nil
}

func (c *customTypeValue) Type() string {
	return c.typeName
}

type customTypeValueBool struct {
	val        *bool
	typeName   string
	defaultStr string
}

func (c *customTypeValueBool) String() string {
	return c.defaultStr
}

func (c *customTypeValueBool) Set(s string) error {
	if s == "true" || s == "1" || s == "" {
		*c.val = true
	} else if s == "false" || s == "0" {
		*c.val = false
	} else {
		return fmt.Errorf("invalid boolean value %s", s)
	}
	return nil
}

func (c *customTypeValueBool) Type() string {
	return c.typeName
}

type customTypeValueInt struct {
	val      *int
	typeName string
}

func (c *customTypeValueInt) String() string {
	if c.val != nil && *c.val != 0 {
		return fmt.Sprintf("%d", *c.val)
	}
	return ""
}

func (c *customTypeValueInt) Set(s string) error {
	var v int
	_, err := fmt.Sscanf(s, "%d", &v)
	if err == nil {
		*c.val = v
	}
	return err
}

func (c *customTypeValueInt) Type() string {
	return c.typeName
}
EOF"}
